<?php
namespace App\Http\Controllers;
use App\Models\{Astrologer,AstrologyService,Faq,Puja,Testimonial}; use Illuminate\Http\Request;
class SiteController extends Controller { public function home(){return view('home',['featured'=>Puja::where('is_featured',true)->take(3)->get(),'services'=>AstrologyService::take(4)->get(),'testimonials'=>Testimonial::where('is_published',true)->take(3)->get(),'faqs'=>Faq::where('is_published',true)->orderBy('sort_order')->take(4)->get()]);} public function services(){return view('services');} public function posts(){return view('posts');} public function astrology(Request $request){$guidance=['muhurat'=>['title'=>'Auspicious muhurat for new beginnings','description'=>'नई शुरुआत के लिए सही मुहूर्त चुनने से कार्य में शुभता, सफलता और सकारात्मक ऊर्जा आती है।'],'navgraha'=>['title'=>'Understanding the Navgrahas','description'=>'नवग्रहों के प्रभाव को समझकर जीवन में संतुलन और सही दिशा पाने का मार्ग जानें।'],'vastu'=>['title'=>'A calm home through Vastu','description'=>'वास्तु के सरल उपायों से घर में शांति, संतुलन और सुखद ऊर्जा बनाए रखें।'],'family-puja'=>['title'=>'Preparing for a family puja','description'=>'परिवार की पूजा के लिए आवश्यक तैयारी, सामग्री और संकल्प की जानकारी प्राप्त करें।']]; return view('astrology.index',['services'=>AstrologyService::all(),'guidance'=>$guidance,'selectedGuidance'=>$guidance[$request->query('guidance')] ?? null]);} public function astrologers(){return view('astrologers.index',['astrologers'=>Astrologer::all()]);} public function mahakal(){return view('mahakal');} public function contact(){return view('contact');} public function contactStore(Request $r){$data=$r->validate(['name'=>'required|max:255','email'=>'required|email','mobile'=>'nullable|max:20','subject'=>'nullable|max:255','message'=>'required|max:3000']); \DB::table('contact_messages')->insert($data+['created_at'=>now(),'updated_at'=>now()]); return back()->with('success','Thank you. Our team will be in touch shortly.');} }
